  1 | // Adapted from shadcn/ui use-toast hook.
  2 | import * as React from "react"
  3 | 
  4 | import type {
  5 |   ToastProps,
  6 | } from "@/components/ui/toast"
  7 | 
  8 | const TOAST_LIMIT = 3
  9 | const TOAST_REMOVE_DELAY = 3000
 10 | 
 11 | type ToasterToast = ToastProps & {
 12 |   id: string
 13 |   title?: React.ReactNode
 14 |   description?: React.ReactNode
 15 | }
 16 | 
 17 | const actionTypes = {
 18 |   ADD_TOAST: "ADD_TOAST",
 19 |   UPDATE_TOAST: "UPDATE_TOAST",
 20 |   DISMISS_TOAST: "DISMISS_TOAST",
 21 |   REMOVE_TOAST: "REMOVE_TOAST",
 22 | } as const
 23 | 
 24 | let count = 0
 25 | 
 26 | function genId() {
 27 |   count = (count + 1) % Number.MAX_SAFE_INTEGER
 28 |   return count.toString()
 29 | }
 30 | 
 31 | type ActionType = typeof actionTypes
 32 | 
 33 | type Action =
 34 |   | { type: ActionType["ADD_TOAST"]; toast: ToasterToast }
 35 |   | { type: ActionType["UPDATE_TOAST"]; toast: Partial<ToasterToast> }
 36 |   | { type: ActionType["DISMISS_TOAST"]; toastId?: string }
 37 |   | { type: ActionType["REMOVE_TOAST"]; toastId?: string }
 38 | 
 39 | interface State {
 40 |   toasts: ToasterToast[]
 41 | }
 42 | 
 43 | const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>()
 44 | 
 45 | function addToRemoveQueue(toastId: string) {
 46 |   if (toastTimeouts.has(toastId)) return
 47 |   const timeout = setTimeout(() => {
 48 |     toastTimeouts.delete(toastId)
 49 |     dispatch({ type: "REMOVE_TOAST", toastId })
 50 |   }, TOAST_REMOVE_DELAY)
 51 |   toastTimeouts.set(toastId, timeout)
 52 | }
 53 | 
 54 | export function reducer(state: State, action: Action): State {
 55 |   switch (action.type) {
 56 |     case "ADD_TOAST":
 57 |       return {
 58 |         ...state,
 59 |         toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
 60 |       }
 61 |     case "UPDATE_TOAST":
 62 |       return {
 63 |         ...state,
 64 |         toasts: state.toasts.map((t) =>
 65 |           t.id === action.toast.id ? { ...t, ...action.toast } : t
 66 |         ),
 67 |       }
 68 |     case "DISMISS_TOAST": {
 69 |       const { toastId } = action
 70 |       if (toastId) {
 71 |         addToRemoveQueue(toastId)
 72 |       } else {
 73 |         state.toasts.forEach((t) => addToRemoveQueue(t.id))
 74 |       }
 75 |       return {
 76 |         ...state,
 77 |         toasts: state.toasts.map((t) =>
 78 |           t.id === toastId || toastId === undefined
 79 |             ? { ...t, open: false }
 80 |             : t
 81 |         ),
 82 |       }
 83 |     }
 84 |     case "REMOVE_TOAST":
 85 |       if (action.toastId === undefined) {
 86 |         return { ...state, toasts: [] }
 87 |       }
 88 |       return {
 89 |         ...state,
 90 |         toasts: state.toasts.filter((t) => t.id !== action.toastId),
 91 |       }
 92 |   }
 93 | }
 94 | 
 95 | const listeners: Array<(state: State) => void> = []
 96 | 
 97 | let memoryState: State = { toasts: [] }
 98 | 
 99 | function dispatch(action: Action) {
100 |   memoryState = reducer(memoryState, action)
101 |   listeners.forEach((listener) => listener(memoryState))
102 | }
103 | 
104 | type Toast = Omit<ToasterToast, "id">
105 | 
106 | function toast({ ...props }: Toast) {
107 |   const id = genId()
108 |   const update = (props: ToasterToast) =>
109 |     dispatch({ type: "UPDATE_TOAST", toast: { ...props, id } })
110 |   const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })
111 | 
112 |   dispatch({
113 |     type: "ADD_TOAST",
114 |     toast: {
115 |       ...props,
116 |       id,
117 |       open: true,
118 |       onOpenChange: (open) => {
119 |         if (!open) dismiss()
120 |       },
121 |     },
122 |   })
123 | 
124 |   return { id, dismiss, update }
125 | }
126 | 
127 | function useToast() {
128 |   const [state, setState] = React.useState<State>(memoryState)
129 | 
130 |   React.useEffect(() => {
131 |     listeners.push(setState)
132 |     return () => {
133 |       const index = listeners.indexOf(setState)
134 |       if (index > -1) listeners.splice(index, 1)
135 |     }
136 |   }, [state])
137 | 
138 |   return {
139 |     ...state,
140 |     toast,
141 |     dismiss: (toastId?: string) => dispatch({ type: "DISMISS_TOAST", toastId }),
142 |   }
143 | }
144 | 
145 | export { useToast, toast }

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

